package io.rcrm.api.pojo.externalJobBoards;

public class ZipRecruiterJobRecord {

	private String start_date_precision;
	private String position;
	private String description;
	private String start_date;
	private String end_date_precision;
	private String employer;
	private String current;
	private String end_date;
	
	public ZipRecruiterJobRecord() {
		super();
		// TODO Auto-generated constructor stub
	}
	public String getStart_date_precision() {
		return start_date_precision;
	}
	public void setStart_date_precision(String start_date_precision) {
		this.start_date_precision = start_date_precision;
	}
	public String getPosition() {
		return position;
	}
	public void setPosition(String position) {
		this.position = position;
	}
	public String getDescription() {
		return description;
	}
	public void setDescription(String description) {
		this.description = description;
	}
	public String getStart_date() {
		return start_date;
	}
	public void setStart_date(String start_date) {
		this.start_date = start_date;
	}
	public String getEnd_date_precision() {
		return end_date_precision;
	}
	public void setEnd_date_precision(String end_date_precision) {
		this.end_date_precision = end_date_precision;
	}
	public String getEmployer() {
		return employer;
	}
	public void setEmployer(String employer) {
		this.employer = employer;
	}
	public String getCurrent() {
		return current;
	}
	public void setCurrent(String current) {
		this.current = current;
	}
	public String getEnd_date() {
		return end_date;
	}
	public void setEnd_date(String end_date) {
		this.end_date = end_date;
	}
	
}
